import sys
sys.setrecursionlimit(1 << 25)

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    q = int(next(it))

    arr = [int(next(it)) for _ in range(n)]

    size = 4 * n
    tree = [0] * size
    lazy = [0] * size

    def build(node, start, end):
        if start == end:
            tree[node] = arr[start]
        else:
            mid = (start + end) // 2
            build(2 * node, start, mid)
            build(2 * node + 1, mid + 1, end)
            tree[node] = min(tree[2 * node], tree[2 * node + 1])

    if n > 0:
        build(1, 0, n - 1)

    def push(node, start, end):
        if lazy[node] != 0:
            tree[node] += lazy[node]
            if start != end:
                lazy[2 * node] += lazy[node]
                lazy[2 * node + 1] += lazy[node]
            lazy[node] = 0

    def update_range(node, start, end, l, r, val):
        push(node, start, end)
        if start > r or end < l:
            return
        if l <= start and end <= r:
            lazy[node] += val
            push(node, start, end)
            return
        mid = (start + end) // 2
        update_range(2 * node, start, mid, l, r, val)
        update_range(2 * node + 1, mid + 1, end, l, r, val)
        tree[node] = min(tree[2 * node], tree[2 * node + 1])

    def query_range(node, start, end, l, r):
        if start > r or end < l:
            return float('inf')
        push(node, start, end)
        if l <= start and end <= r:
            return tree[node]
        mid = (start + end) // 2
        left_val = query_range(2 * node, start, mid, l, r)
        right_val = query_range(2 * node + 1, mid + 1, end, l, r)
        return min(left_val, right_val)

    output = []
    for _ in range(q):
        op = int(next(it))
        if op == 1:
            l = int(next(it)) - 1
            r = int(next(it)) - 1
            val = int(next(it))
            if n > 0:
                update_range(1, 0, n - 1, l, r, val)
        else:
            l = int(next(it)) - 1
            r = int(next(it)) - 1
            if n == 0:
                output.append("-1")
            else:
                res = query_range(1, 0, n - 1, l, r)
                output.append(str(res))

    print('\n'.join(output))

if __name__ == "__main__":
    main()
